//! Thread CPU-pinning helpers: `--pin-cpus` parsing, affinity
//! snapshot and restore, human-readable mask/plan summaries, and
//! the pool's placement, what its CPUs share.

use std::collections::BTreeSet;
use std::path::Path;

/// Parse a `--pin-cpus` value (comma-separated list with optional ranges)
/// into an ordered vector of CPU ids (the kernel's schedulable unit, sysfs
/// `cpuN`). Accepts forms like `"0,1"`, `"0-11"`, `"0,3-5,7"`. Duplicates
/// are preserved in the given order so oversubscription (`"0,0,0"`) works.
pub fn parse_cpus(spec: &str) -> Result<Vec<usize>, String> {
    let mut out = Vec::new();
    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        match part.split_once('-') {
            None => out.push(
                part.parse::<usize>()
                    .map_err(|e| format!("invalid CPU id {part:?}: {e}"))?,
            ),
            Some((lo, hi)) => {
                let lo = lo
                    .trim()
                    .parse::<usize>()
                    .map_err(|e| format!("invalid range start {lo:?}: {e}"))?;
                let hi = hi
                    .trim()
                    .parse::<usize>()
                    .map_err(|e| format!("invalid range end {hi:?}: {e}"))?;
                if hi < lo {
                    return Err(format!("range {lo}-{hi} is empty"));
                }
                out.extend(lo..=hi);
            }
        }
    }
    Ok(out)
}

/// Print the current thread's CPU id to stderr with a label.
/// Useful for debugging pinning — not called in normal paths.
#[allow(dead_code)]
pub fn print_cpu_id(prompt: &str) {
    let cid = unsafe { libc::sched_getcpu() };
    eprintln!("{prompt}: cid={cid}");
}

/// Pin the current thread to `logical_cpu`. No-op if `None`.
///
/// Constructs a `CoreId` directly rather than querying
/// `get_core_ids()`, which only returns cores in the caller's
/// current affinity mask — after the first pin that mask is
/// narrowed and subsequent lookups for other cores would fail.
pub fn pin_current(logical_cpu: Option<usize>) {
    let Some(target) = logical_cpu else { return };
    core_affinity::set_for_current(core_affinity::CoreId { id: target });
}

/// Read the current thread's CPU affinity mask, or `None` if the
/// syscall fails (very unusual on Linux).
pub fn current_affinity() -> Option<libc::cpu_set_t> {
-----
//! The run's parameters as resolved: each one's value and where the value came from.
//!
//! A value reaches a run from a built-in default, a config file, or a flag, and the report used
//! to print some values and no sources, so a reader could not tell a box's declared `blocks`
//! from the built-in, or a flag typed from one forgotten. The `Config:` list prints every
//! parameter with its source, and marks a source that restates the default, since that value
//! would survive the source's removal unchanged.

use std::path::Path;

use crate::config::Config;

/// Where a resolved value came from.
#[derive(Debug, Clone, PartialEq)]
pub enum Source {
    /// No file and no flag set it.
    Default,
    /// A config file set it, the path as loaded.
    File(std::path::PathBuf),
    /// A flag set it, as typed on the line (`--blocks`), with any qualifier the value needs.
    Flag(String),
}

/// One run parameter: its config-key-style name, its value as the report prints it, and its
/// source.
#[derive(Debug, Clone, PartialEq)]
pub struct Param {
    /// The parameter's name, the config key where one exists (`block_sleep`).
    pub key: &'static str,
    /// The resolved value, rendered.
    pub value: String,
    /// Where the value came from.
    pub source: Source,
    /// A file or flag set the value to what the default would have given.
    pub same_as_default: bool,
}

impl Param {
    /// A parameter whose value is `value` and whose default renders as `default`.
    pub fn new(key: &'static str, value: String, default: &str, source: Source) -> Self {
        let same_as_default = source != Source::Default && value == default;
        Param {
            key,
            value,
            source,
            same_as_default,
        }
    }
}

/// Resolve one layered parameter, the flag winning, then the config file, then `default`,
/// returning the value and its source.
pub fn layered<T>(
    flag_value: Option<T>,
    flag: &str,
    file_value: Option<T>,
    key: &str,
    config: &Config,
    default: T,
) -> (T, Source) {
    if let Some(v) = flag_value {
        return (v, Source::Flag(flag.to_string()));
    }
    match (file_value, config.source(key)) {
        (Some(v), Some(path)) => (v, Source::File(path.to_path_buf())),
        (Some(v), None) => (v, Source::Default),
        (None, _) => (default, Source::Default),
    }
}

